Object.assign(T,{
 hydration:{n:"Hydration assessment",p:"46–47",gm:"other",
  how:"Inspect for sunken orbits, dry mucous membranes, a gaunt or moribund look; check axillae and tongue; pinch the skin for turgor; take BP lying then sitting/standing (stand at least 1 minute).",
  look:"Use a combination of signs: dry axillae raise and a moist tongue lower the likelihood of dehydration. Skin turgor is of unproven value, especially in the elderly. Mild (<5%): thirst, dry mucosa; moderate: reduced turgor, tachycardia; severe: postural hypotension, oliguria, collapsed veins."},
 older_exam:{n:"Examination of the older person",p:"830–833",gm:"falls",
  how:"Complete exam plus: postural BP; hydration; skin for pressure sores (stage I–IV), bruises (falls or elder abuse), skin cancer; weight/BMI; systolic murmur (?aortic stenosis); dentition and dry mouth; left lower quadrant faecal mass; rectal exam for impaction; palpable bladder (retention can present as delirium); cognition and primitive reflexes (glabellar tap, palmomental, grasp); gait and balance; vision and hearing; feet and joint function; breasts in women.",
  look:"Kyphosis (crush fractures), AF, aortic valve disease, joint replacement scars, wasting — see the summary figure on p 830."},
 getupgo:{n:"'Get up and go' and functional reach tests",p:"831–832",gm:"falls",
  how:"Get up and go: stand from an armchair, walk ~3 m to a line, turn 180°, walk back and sit down; watch each phase (rising, standing steadiness, gait, turning, sitting) and time it. Functional reach: patient stands with fist extended alongside a wall and leans forward as far as possible without stepping; measure the distance.",
  look:"Normal 7–10 s; >20 s suggests mobility problems (times have only poor-to-moderate accuracy). Difficulty rising from a chair means higher falls risk. Reach <15 cm suggests increased falls risk. Normal gait speed in healthy elderly 1.1–1.5 m/s."},
 minicog:{n:"Mini-Cog cognitive screen",p:"833, 854",gm:"osce",
  how:"Give three words (repeat up to three times to be sure they are registered). Ask the patient to draw a clock face with numbers and set the hands to a given time (e.g. 11.10). Then ask for the three words.",
  look:"1 point per word recalled, 2 points for a fully correct clock (0 if not). Score 0–2 out of 5 supports dementia. Distinguish dementia from delirium (acute, fluctuating)."},
 depression2q:{n:"Two-question depression screen",p:"832, 851",gm:"osce",
  how:"Ask: 'In the past month have you felt down, depressed or hopeless?' and 'Have you felt little interest or pleasure in doing things?'",
  look:"Yes to either → explore in detail (LR+ 2.9, LR− 0.05). Sensitive but less specific, so follow-up questions are needed."},
 mse:{n:"Mental state examination",p:"854–857",gm:"osce",
  how:"Observe throughout the interview and record under headings: appearance; behaviour (motor changes, agitation, retardation); attitude to the examiner; mood and affect (and appropriateness); speech (tempo, dysphasia, dysarthria); perception (hallucinations — with a clear sensorium?); thought form and content (delusions, obsessions, suicidal/homicidal or paranoid ideas); sensorium and cognition (alertness, orientation, short- and long-term memory, serial 7s or WORLD backwards, general knowledge); judgement; insight.",
  look:"Visual hallucinations suggest an organic cause (delirium, epilepsy, alcohol withdrawal, drugs); auditory suggest schizophrenia (or delirium). Clouded consciousness = delirium. Blunted affect, thought disorder = schizophrenia; pressured speech, flight of ideas = mania."},
 risk:{n:"Risk assessment (suicide / harm to others)",p:"851",gm:"osce",
  how:"Ask directly and sensitively: has life seemed not worth living, or have they felt so bad they considered ending it all? If yes: thoughts of killing themselves, how, and any plans. Assess risk to others (best predictor: past threats or harm).",
  look:"Asking does not increase risk. If there is significant risk, seek psychiatry/mental health advice early; involuntary treatment may apply under mental health legislation."},
 seizure_exam:{n:"Examination after a suspected seizure",p:"493–494, 602–604",gm:"neuro",
  how:"Check level of consciousness/GCS and whether they wake drowsy; look for tongue trauma, injuries and incontinence; full neurological exam for focal signs; look for continuing or recurrent convulsions; gum hyperplasia (phenytoin); check glucose.",
  look:"Drowsiness on waking favours seizure over cardiac syncope; tongue biting and incontinence are of limited diagnostic value on their own. Recurrent convulsions = status epilepticus. Complex partial status can reduce consciousness without convulsions."},
 facial:{n:"Facial nerve (VII) examination",p:"526–528",gm:"cn",
  how:"Ask the patient to look up and wrinkle the forehead (push down on each side), shut the eyes tightly (compare how deeply the lashes are buried; try to open them; look for Bell's phenomenon), puff out the cheeks, and grin (compare nasolabial folds). If LMN, check the ear and palate for vesicles. Taste on the anterior two-thirds of the tongue only if needed.",
  look:"UMN lesion: forehead spared (bilateral cortical supply), lower face weak on the opposite side; emotional movements may be preserved. LMN lesion: all muscles on the same side affected, eye rolls up on attempted closure (Bell's phenomenon). Vesicles = Ramsay Hunt syndrome. Bell's palsy causes up to 80% of facial nerve palsies; bilateral weakness → Guillain–Barré, sarcoid, Lyme, etc."},
 dm_feet:{n:"Diabetic foot examination",p:"463–467",gm:"endo",
  how:"Start with the legs. Inspect: hairless atrophic skin, ulcers (toes and pressure areas), Charcot joints (ankles, knees), boils/cellulitis/fungal infection, pigmented scars (dermopathy), necrobiosis lipoidica over the shins, injection sites (fat atrophy/hypertrophy), quadriceps wasting. Palpate: foot temperature, all pulses (auscultate femorals), capillary return. Neurological: peripheral neuropathy including dorsal columns, reflexes, proximal power; monofilament testing.",
  look:"Cold blue feet with absent pulses = vascular disease; a warm swollen foot may be an acute Charcot joint. Ulcers arise from ischaemia plus neuropathy."},
 monofil:{n:"10 g monofilament test",p:"466–467",gm:"endo",
  how:"Show the patient on the arm first. Eyes closed; place the monofilament perpendicular to the skin and press for ~1 second until it buckles; patient says 'yes' when felt. Test the plantar 1st, 3rd and 5th metatarsal heads and the distal hallux.",
  look:"Failure to feel indicates protective sensory loss (peripheral neuropathy)."},
 dm_review:{n:"Diabetes: rest of the examination",p:"465–467",gm:"endo",
  how:"General: weight, hydration, endocrine facies, pigmentation (haemochromatosis), Kussmaul breathing, acetone breath. Arms: skin tags, acanthosis, nails (candida), pulse; BP lying and standing. Eyes: acuity, Argyll Robertson pupils (rare), rubeosis, cataract, retinopathy, III nerve palsy. Mouth (monilia), carotids, chest (infection), abdomen (liver, injection sites), femoral mononeuritis. Urinalysis for glucose, ketones and protein.",
  look:"Postural hypotension suggests autonomic neuropathy."},
 htn_exam:{n:"Examination of the hypertensive patient",p:"124–125",gm:"cvs",
  how:"Inspect for rare secondary causes (Cushing's, acromegaly, polycythaemia, CKD). BP lying and standing with the right-sized cuff. Radiofemoral delay; leg BP if coarctation suspected or severe hypertension before age 30. Fundi. Rest of CVS for LVF and coarctation (S4 common if >180/110). Abdomen: renal or adrenal masses, AAA, renal bruit. CNS for previous stroke. Urinalysis.",
  look:"Retinopathy grades: 1 silver wiring; 2 + AV nipping; 3 + flame haemorrhages/exudates; 4 + papilloedema (grade ≥3 changes = malignant hypertension). Loud systolic–diastolic epigastric bruit suggests renal artery stenosis; short soft left-sided bruits are usually splenic and insignificant."},
 pelvicfloor:{n:"Rectal exam: tone & pelvic floor tests",p:"266–267",gm:"pr",
  how:"Ask the patient to strain while you watch the perineum (leakage, perineal descent >4 cm, patulous anus). On entry assess resting tone. Then: ask them to strain (feel for rectocele); press the posterior wall (puborectalis tenderness); ask them to squeeze (feel the puborectalis 'lift' towards the umbilicus); hand on the abdomen while they strain again (inappropriate Valsalva/abdominal contraction).",
  look:"Reduced tone may mean a sphincter tear; high resting tone can impair evacuation. Consider pelvic floor dysfunction in all chronic constipation."},
 analpain:{n:"Approach to anal pain on examination",p:"264–266",gm:"pr",
  how:"Inspect first (ask the patient to bear down). If entry causes excruciating pain, stop the digital exam.",
  look:"Excruciating pain at the start strongly suggests an anal fissure (often visible, usually posterior midline). Other painful causes: thrombosed external haemorrhoid, ischiorectal abscess, active proctitis, anal ulceration."},
 headinj:{n:"Head injury examination",p:"601–603, 786",gm:"headinj",
  how:"ABC and GCS. Look for scalp and facial injury, Battle's sign (bruising behind the ear), conjunctival haemorrhage, blood or clear fluid from the ears or nose (test watery fluid for glucose = CSF), and inspect the ear canals. Pupils (one dilated pupil = raised ICP / herniation risk), eye position, focal limb signs. Don't test neck flexion if a neck injury is possible.",
  look:"Battle's sign, CSF leak or blood in the canal suggest a base-of-skull fracture."},
 angio:{n:"Anaphylaxis / angio-oedema assessment",p:"870–871",gm:"abcde",
  how:"Airway first: listen for stridor, look for lip/tongue/face swelling and intercostal recession; breathing (RR, accessory muscles, SpO2, wheeze); circulation (pulse, BP, capillary refill, perfusion); inspect the skin.",
  look:"A threatened airway from angio-oedema, stridor, SpO2 <90% on oxygen or SBP <100 mmHg are signs of a critically ill patient."},
 tox:{n:"Toxicology / intoxication examination",p:"601–604, 856–858",gm:"abcde",
  how:"ABC, GCS, glucose. Breathing pattern; colour (cherry red in CO poisoning, rare); pupils; mouth (corrosion from caustics, tongue trauma); smell the breath (alcohol, ketones, hepatic fetor, uraemia); injection marks; look for injuries. In withdrawal look for agitation, tremor and hallucinations.",
  look:"Pinpoint but reactive pupils: opiates (or pontine lesion). Midpoint non-reactive or widely dilated: anticholinergics. Visual hallucinations: alcohol withdrawal (delirium tremens), drug intoxication. Remember alcohol ingestion may be associated with head injury."},
 sepsis_screen:{n:"Sepsis screen (SIRS / qSOFA)",p:"871",gm:"sepsis",
  how:"Temperature, HR, RR, BP and mental state; look at the skin for a meningococcal (non-blanching) rash; take blood and urine cultures if febrile.",
  look:"SIRS: ≥2 of temp >38.3 or <36 °C, HR >90, RR >20, abnormal WCC (sensitive, not specific). qSOFA 1 point each for RR ≥22, SBP ≤100, altered mentation; ≥2 = poor outcome."},
 cellulitis:{n:"Cellulitis / skin infection assessment",p:"116, 463, 817",gm:"skin",
  how:"Inspect the extent of erythema and mark it; feel warmth and tenderness; look for a raised, sharply demarcated edge (erysipelas), lymphangitic streaks and tender regional (e.g. inguinal) nodes; search for the entry point (injury, tinea pedis between the toes, varicose ulcer, injection sites); check for diabetes and for DVT; compare both legs.",
  look:"Cellulitis is unilateral — bilateral red swollen legs are usually venous stasis/eczema, often misdiagnosed as cellulitis. Upper limb involvement in IV drug users."}
});
